{
  "rules": [
    {
      "category": "algorithmic_rent_setting",
      "title": "Berkeley Coordinated Pricing Algorithm Ban",
      "requirement": "Landlords are prohibited from using coordinated pricing algorithms that rely on competitor data to set rents or manage occupancy levels for residential units. The sale, licensing, or provision of such algorithms to Berkeley landlords is also illegal.",
      "requirement_es": "Se prohíbe a los propietarios utilizar algoritmos de fijación coordinada de precios que utilicen datos de la competencia para fijar alquileres o gestionar niveles de ocupación en unidades residenciales. También es ilegal vender, licenciar o proporcionar dichos algoritmos a propietarios en Berkeley.",
      "key_value": null,
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Reports published by a trade association receiving renter data and publishing it in an aggregated and anonymous manner",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Products used for the purpose of establishing rent or income limits in accordance with affordable housing guidelines of a local, state, or federal government",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "product used to establish rent or income limits under affordable housing guidelines"
              }
            ]
          }
        }
      ],
      "effective_date": "2026-03-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Civil penalties up to $1,000 per violation (each separate month and each separate unit constitutes a violation), damages, injunctive relief, restitution/return of illegal profits, and prevailing attorney's fees and costs.",
      "source_citation": "Berkeley Mun. Code § 13.63.030",
      "quote": {
        "chunk": "c8",
        "start_words": "It shall be unlawful for a landlord",
        "end_words": "in the city of Berkeley."
      },
      "confidence": 0.95
    }
  ]
}
